 1	"use server";
 2	
 3	/**
 4	 * Registers a webhook endpoint; plan and flag gated.
 5	 *
 6	 * Owner D. Two independent gates: the `webhooks` feature flag (which is itself
 7	 * plan-derived) and the numeric `webhooks` quota. Both are checked because a
 8	 * flag can be force-enabled through an org override while the quota still
 9	 * applies.
10	 *
11	 * Must call (do not reimplement): createWebhookSchema, can, isEnabled,
12	 * getPlanLimits, getActor, toActionResult
13	 */
14	
15	import {
16	  FeatureUnavailableError,
17	  ForbiddenActionError,
18	  PlanLimitError,
19	} from "@/actions/_lib/action-errors";
20	import { withAction } from "@/actions/_lib/with-action";
21	import { getPlanLimits } from "@/config/plan-limits";
22	import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
23	import { isEnabled } from "@/lib/feature-flags";
24	import { can } from "@/lib/permissions";
25	import { createWebhookSchema, type CreateWebhookInput } from "@/schemas/webhook";
26	import { buildFlagContext } from "@/server/services/feature-flag-service";
27	import { getOrganizationSummary } from "@/server/services/organization-service";
28	import { createWebhook, listWebhooks } from "@/server/services/webhook-service";
29	import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
30	import type { ActionResult } from "@/types/api";
31	
32	const run = withAction<typeof createWebhookSchema, WebhookEndpointRow>(
33	  createWebhookSchema,
34	  async (raw, actor) => {
35	    const input = raw as CreateWebhookInput;
36	
37	    const allowed = can(actor, "webhook:manage", {
38	      kind: "webhook",
39	      orgId: input.orgId,
40	      webhookId: null,
41	    });
42	    if (!allowed) {
43	      throw new ForbiddenActionError("webhook:manage");
44	    }
45	
46	    const { organization } = await getOrganizationSummary(actor, input.orgId);
47	    if (!isEnabled("webhooks", buildFlagContext(actor, organization))) {
48	      throw new FeatureUnavailableError("webhooks");
49	    }
50	
51	    const limits = getPlanLimits(organization.plan);
52	    const existing = await listWebhooks(actor, input.orgId);
53	    if (existing.length >= limits.webhooks) {
54	      throw new PlanLimitError("webhooks", limits.webhooks, existing.length);
55	    }
56	
57	    const endpoint = await createWebhook(actor, input);
58	    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.hours);
59	    return endpoint;
60	  },
61	  { revalidate: ["webhooks"], cacheProfile: "hours" },
62	);
63	
64	export async function createWebhookAction(
65	  raw: unknown,
66	): Promise<ActionResult<WebhookEndpointRow>> {
67	  return run(raw);
68	}

